<template>
<div class="office-page board-page" v-loading="loading">
 <header class="office-toolbar"><div class="office-actions board-heading"><el-button circle title="返回白板列表" @click="router.push('/whiteboard')"><span class="material-symbols-outlined">arrow_back</span></el-button><h2>{{ title }}</h2><span class="office-muted">{{ saving?'保存中':canEdit?'已保存':'只读' }}</span></div><div class="office-actions"><el-button circle title="操作历史" @click="historyOpen=true"><span class="material-symbols-outlined">history</span></el-button><el-button circle title="保存为模板" :disabled="!canEdit||saving" @click="capture"><span class="material-symbols-outlined">dashboard_customize</span></el-button><el-button circle title="下载PNG图片" @click="exportImage"><span class="material-symbols-outlined">download</span></el-button><el-button circle title="清空白板" :disabled="!canEdit||saving" @click="clear"><span class="material-symbols-outlined">delete_sweep</span></el-button></div></header>
 <div class="board-toolbar" role="toolbar" aria-label="白板工具"><el-radio-group v-model="tool" size="small" aria-label="绘制工具"><el-radio-button v-for="item in tools" :key="item.id" :value="item.id" :title="item.label" :aria-label="item.label"><span class="material-symbols-outlined">{{ item.icon }}</span></el-radio-button></el-radio-group><label class="color-control" title="画笔颜色"><input v-model="color" type="color" aria-label="画笔颜色"/></label><el-input-number v-model="width" :min="1" :max="20" size="small" aria-label="画笔粗细"/><el-button circle title="撤销" :disabled="!canUndo||saving||!canEdit" @click="undo"><span class="material-symbols-outlined">undo</span></el-button><el-button circle title="重做" :disabled="!redoIds.length||saving||!canEdit" @click="redo"><span class="material-symbols-outlined">redo</span></el-button><el-button circle title="缩小" :disabled="zoom<=.25" @click="changeZoom(-.1)"><span class="material-symbols-outlined">zoom_out</span></el-button><span class="zoom-label">{{ Math.round(zoom*100) }}%</span><el-button circle title="放大" :disabled="zoom>=2" @click="changeZoom(.1)"><span class="material-symbols-outlined">zoom_in</span></el-button><el-button circle title="适应画布" @click="fit"><span class="material-symbols-outlined">fit_screen</span></el-button><el-select v-model="background" aria-label="画布背景" size="small"><el-option label="纯白" value="plain"/><el-option label="网格" value="grid"/><el-option label="点阵" value="dot"/></el-select><el-select v-model="follow" clearable placeholder="跟随视图" aria-label="跟随协作者视图" size="small"><el-option v-for="peer in livePeers" :key="peer.client" :value="peer.client" :label="peer.name"/></el-select></div>
 <div class="board-presence"><span :class="{online:connected}">{{ connected?'实时同步':'自动保存' }}</span><span v-for="peer in livePeers" :key="peer.client">{{ peer.name }}</span><span>{{ activity }}</span><span>{{ activeCount }} 个操作</span></div>
 <el-alert v-if="error" type="error" :title="error" :closable="false"><el-button size="small" :disabled="saving" @click="retry">重试保存</el-button><el-button size="small" @click="backup">下载本地备份</el-button></el-alert>
 <div ref="viewport" class="board-viewport" @scroll="broadcast()" @wheel.ctrl.prevent="wheel"><div class="board-space" :style="{width:1920*zoom+'px',height:1080*zoom+'px'}"><div class="board-layer" :style="{transform:`scale(${zoom})`}"><canvas ref="canvas" width="1920" height="1080" class="drawing-canvas" :class="{panning:tool==='pan'}" aria-label="协作白板画布" @pointerdown="down" @pointermove="move" @pointerup="up" @pointercancel="cancelDrawing"/><div v-for="peer in livePeers.filter(p=>Number.isFinite(p.x)&&Number.isFinite(p.y))" :key="peer.client" class="peer-cursor" :style="{left:peer.x+'px',top:peer.y+'px',color:peer.color||'#3370ff'}"><span class="material-symbols-outlined">near_me</span><small>{{ peer.name }}</small></div></div></div></div>
 <el-dialog v-model="historyOpen" title="白板操作历史" width="min(560px, 94vw)" class="board-dialog"><div v-for="op in [...operations].reverse().slice(0,100)" :key="op.elementId" class="board-history"><div><strong>{{ toolName(op.tool) }}</strong><p class="office-muted">{{ op.actorId===userId?'我':'成员 '+op.actorId }} · {{ String(op.createdAt||'').replace('T',' ') }}</p></div><el-tag v-if="!op.active" type="info">已撤销</el-tag><el-button v-if="canEdit&&op.actorId===userId" :disabled="saving" @click="toggle(op,!op.active)">{{ op.active?'撤销':'恢复' }}</el-button></div><el-empty v-if="!operations.length" description="暂无绘制操作"/></el-dialog>
</div>
</template>
<script setup lang="ts">
import {computed,nextTick,onMounted,onBeforeUnmount,reactive,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {ElMessage,ElMessageBox} from 'element-plus'
import request from '@/utils/request'
import {wsClient} from '@/utils/wsClient'
import {getToken} from '@/utils/token'
import {drawOperation,type BoardOperation} from './drawing'
const route=useRoute(),router=useRouter(),id=String(route.params.docId),title=ref('协作白板'),loading=ref(false),saving=ref(false),canEdit=ref(false),error=ref(''),tool=ref('pen'),color=ref('#3370ff'),width=ref(3),zoom=ref(1),background=ref('plain'),canvas=ref<HTMLCanvasElement>(),viewport=ref<HTMLDivElement>(),historyOpen=ref(false),operations=ref<BoardOperation[]>([]),legacy=ref<any[]>([]),redoIds=ref<number[]>([]),userId=ref(''),name=ref('协作者'),follow=ref(''),connected=ref(false),activity=ref('')
const tools=[{id:'pan',label:'平移',icon:'pan_tool'},{id:'pen',label:'画笔',icon:'edit'},{id:'rect',label:'矩形',icon:'rectangle'},{id:'circle',label:'圆形',icon:'circle'},{id:'triangle',label:'三角形',icon:'change_history'},{id:'arrow',label:'箭头',icon:'arrow_right_alt'},{id:'line',label:'线条',icon:'horizontal_rule'},{id:'text',label:'文字',icon:'title'},{id:'eraser',label:'橡皮',icon:'ink_eraser'}]
const toolName=(id:string)=>id==='clear'?'清空':tools.find(t=>t.id===id)?.label||id
const client=crypto.randomUUID(),peers=reactive<Record<string,any>>({}),clock=ref(Date.now()),livePeers=computed(()=>Object.values(peers).filter(p=>clock.value-p.time<30000)),activeCount=computed(()=>operations.value.filter(o=>o.active).length),canUndo=computed(()=>operations.value.some(o=>o.active&&o.actorId===userId.value))
let draft:BoardOperation|undefined,pending:BoardOperation|undefined,pan:{x:number;y:number;left:number;top:number}|undefined,lastCursor=0,poll:ReturnType<typeof setInterval>|undefined,removeWs:(()=>void)[]=[],disposed=false,fetching=false
function parse(v:any){try{return typeof v==='string'?JSON.parse(v):v||{}}catch{return {}}}
function accept(rows:any[]){operations.value=[];legacy.value=[];for(const row of rows){if(row.type==='operation'){const op=parse(row.content),meta=parse(row.metadata);operations.value.push({...op,elementId:row.id,actorId:String(meta.actorId),active:meta.active!==false,createdAt:row.create_time})}else if(row.type==='drawing'){const old=parse(row.content);if(Array.isArray(old))legacy.value.push(...old.flat())}else{const p=parse(row.position||row.position_json),s=parse(row.style||row.style_json);legacy.value.push({tool:row.type,color:s.color||'#333333',width:s.width||3,x:p.x||0,y:p.y||0,w:(p.x||0)+(p.width||100),h:(p.y||0)+(p.height||60),text:row.content})}}redraw()}
async function load(){if(fetching||disposed)return;fetching=true;try{const r:any=await request.get(`/whiteboard/${id}/operations`);if(!disposed)accept(r.data)}finally{fetching=false}}
function redraw(target=canvas.value,includeDraft=true){if(!target)return;const c=target.getContext('2d');if(!c)return;c.clearRect(0,0,1920,1080);c.fillStyle='#ffffff';c.fillRect(0,0,1920,1080);if(background.value!=='plain'){c.strokeStyle='#edf0f3';c.fillStyle='#d5dbe4';c.lineWidth=1;for(let x=0;x<1920;x+=24)for(let y=0;y<1080;y+=24){if(background.value==='dot')c.fillRect(x,y,1,1);else{c.beginPath();c.moveTo(x,y);c.lineTo(x+24,y);c.moveTo(x,y);c.lineTo(x,y+24);c.stroke()}}}for(const old of legacy.value)drawOperation(c,old);for(const op of operations.value)if(op.active)drawOperation(c,op);if(includeDraft&&draft)drawOperation(c,draft)}
watch(background,()=>redraw())
function position(e:PointerEvent){const r=canvas.value!.getBoundingClientRect();return [Math.round(Math.max(0,Math.min(1920,(e.clientX-r.left)/zoom.value))),Math.round(Math.max(0,Math.min(1080,(e.clientY-r.top)/zoom.value)))] as [number,number]}
async function down(e:PointerEvent){if(e.button!==0||saving.value||pending)return;const point=position(e);(e.currentTarget as HTMLCanvasElement).setPointerCapture(e.pointerId);if(tool.value==='pan'){pan={x:e.clientX,y:e.clientY,left:viewport.value!.scrollLeft,top:viewport.value!.scrollTop};return}if(!canEdit.value)return;follow.value='';draft={id:crypto.randomUUID(),tool:tool.value,color:color.value,width:width.value,x:point[0],y:point[1],w:point[0],h:point[1],points:[point]};if(tool.value==='text'){const entry=draft;draft=undefined;try{const result=await ElMessageBox.prompt('文字','添加文字',{inputValidator:v=>!!v?.trim()&&v.length<=500||'请输入1到500字'});entry.text=result.value;await save(entry)}catch{}}}
function move(e:PointerEvent){const [x,y]=position(e);if(Date.now()-lastCursor>100){broadcast(x,y);lastCursor=Date.now()}if(pan&&viewport.value){viewport.value.scrollLeft=pan.left+pan.x-e.clientX;viewport.value.scrollTop=pan.top+pan.y-e.clientY;return}if(!draft)return;draft.w=x;draft.h=y;if(['pen','eraser'].includes(draft.tool)&&draft.points!.length<2000)draft.points!.push([x,y]);redraw()}
async function up(){if(pan){pan=undefined;broadcast();return}if(!draft)return;const op=draft;draft=undefined;await save(op)}
function cancelDrawing(){pan=undefined;draft=undefined;redraw()}
async function save(op:BoardOperation){saving.value=true;error.value='';pending=op;try{const r:any=await request.post(`/whiteboard/${id}/operations`,op);accept(r.data);pending=undefined;redoIds.value=[];wsClient.send('WHITEBOARD_DRAW',{client,name:name.value},id)}catch(e:any){error.value=e.message||'保存失败，操作保留在本机';draft=op;redraw();draft=undefined}finally{saving.value=false}}
async function retry(){if(pending)await save(pending)}
function backup(){download(new Blob([JSON.stringify({boardId:id,operations:operations.value,legacy:legacy.value,pending},null,2)],{type:'application/json'}),'json')}
async function toggle(op:BoardOperation,active:boolean){saving.value=true;try{const r:any=await request.put(`/whiteboard/${id}/operations/${op.elementId}/active`,{active});accept(r.data);wsClient.send('WHITEBOARD_DRAW',{client,name:name.value},id)}catch(e:any){error.value=e.message}finally{saving.value=false}}
async function undo(){const op=[...operations.value].reverse().find(o=>o.active&&o.actorId===userId.value);if(op){await toggle(op,false);if(!operations.value.find(o=>o.id===op.id)?.active)redoIds.value.push(op.elementId!)}}
async function redo(){const element=redoIds.value.pop(),op=operations.value.find(o=>o.elementId===element);if(op)await toggle(op,true)}
async function clear(){try{await ElMessageBox.confirm('清空当前画布？可通过撤销恢复。','清空白板');await save({id:crypto.randomUUID(),tool:'clear',color:color.value,width:width.value,x:0,y:0,w:0,h:0})}catch{}}
function changeZoom(delta:number){zoom.value=Math.max(.25,Math.min(2,Math.round((zoom.value+delta)*100)/100));broadcast()}
function wheel(e:WheelEvent){changeZoom(e.deltaY<0?.1:-.1)}
function fit(){zoom.value=Math.max(.25,Math.min(1,(viewport.value?.clientWidth||800)/1920));if(viewport.value){viewport.value.scrollLeft=0;viewport.value.scrollTop=0}broadcast()}
function broadcast(x?:number,y?:number){if(connected.value&&!follow.value)wsClient.send('DOC_CURSOR',{kind:'whiteboard',client,name:name.value,color:color.value,x,y,zoom:zoom.value,left:viewport.value?.scrollLeft||0,top:viewport.value?.scrollTop||0},id)}
async function capture(){try{const r=await ElMessageBox.prompt('模板名称','保存为模板',{inputValue:title.value,inputValidator:v=>!!v?.trim()&&v.length<=100||'请输入1到100字'});await request.post('/template/create',{sourceDocId:id,name:r.value,category:'白板'});ElMessage.success('已保存至模板中心')}catch{}}
function download(blob:Blob,ext:string){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=title.value.replace(/[\\/:*?"<>|]/g,'_')+'.'+ext;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}
async function exportImage(){try{await request.get(`/whiteboard/${id}/operations/export-check`);const output=document.createElement('canvas');output.width=1920;output.height=1080;redraw(output,false);output.toBlob(b=>{if(b)download(b,'png')})}catch{}}
onMounted(async()=>{loading.value=true;try{const [d,u]:any[]=await Promise.all([request.get('/document/'+id),request.get('/user/info')]);title.value=d.data.title;canEdit.value=d.data.canEdit===true;userId.value=String(u.data.userId);name.value=u.data.nickname||u.data.username;await load();await nextTick();fit();wsClient.connect(getToken()||undefined);removeWs.push(wsClient.onStatusChange(ok=>{connected.value=ok;if(ok){wsClient.send('DOC_JOIN',{},id);broadcast();load().catch(()=>{})}}),wsClient.on('whiteboard_draw_broadcast',data=>{if(data.roomId===id&&data.client!==client){activity.value=(data.name||'协作者')+' 更新了白板';load().catch(()=>{})}}),wsClient.on('doc_cursor_broadcast',async data=>{if(data.roomId!==id||data.kind!=='whiteboard'||data.client===client)return;if(!peers[data.client]){activity.value=data.name+' 加入了白板';broadcast()}peers[data.client]={...data,x:data.x??peers[data.client]?.x,y:data.y??peers[data.client]?.y,time:Date.now()};if(follow.value===data.client&&viewport.value){zoom.value=Math.max(.25,Math.min(2,data.zoom||1));await nextTick();viewport.value.scrollLeft=data.left||0;viewport.value.scrollTop=data.top||0}}));poll=setInterval(()=>{clock.value=Date.now();for(const p of Object.values(peers))if(!p.expired&&clock.value-p.time>30000){p.expired=true;activity.value=p.name+' 离开了白板'}broadcast();if(!saving.value&&!draft&&!pending)load().catch(()=>{})},5000)}catch(e:any){error.value=e.message}finally{loading.value=false}})
onBeforeUnmount(()=>{disposed=true;if(poll)clearInterval(poll);removeWs.forEach(fn=>fn());wsClient.send('DOC_LEAVE',{},id)})
</script>
<style scoped>
.board-page{display:flex;flex-direction:column;gap:var(--space-2);height:calc(100dvh - 120px);min-height:500px}.board-heading{min-width:0;flex:1;flex-wrap:wrap}.board-heading h2{font-size:var(--text-section);overflow-wrap:anywhere;margin:0}.board-toolbar{display:flex;align-items:center;flex-wrap:wrap;gap:8px}.board-toolbar .el-button+.el-button{margin:0}.board-toolbar .el-select{width:124px}.board-toolbar .el-input-number{width:108px}.board-toolbar .material-symbols-outlined{font-size:18px}.board-toolbar :deep(.el-radio-button__inner){padding:6px 8px}.color-control{display:flex;align-items:center}.color-control input{width:32px;height:28px;border:1px solid var(--c-border);border-radius:var(--radius-sm);padding:2px;background:var(--c-surface)}.zoom-label{width:40px;font-size:12px;text-align:center}.board-presence{display:flex;flex-wrap:wrap;gap:12px;font-size:12px;color:var(--c-text-secondary);min-height:18px}.online{color:var(--c-success)}.board-viewport{flex:1;min-height:220px;overflow:auto;border:1px solid var(--c-border);border-radius:var(--radius-sm);background:var(--c-bg)}.board-space{position:relative}.board-layer{position:absolute;left:0;top:0;width:1920px;height:1080px;transform-origin:0 0}.drawing-canvas{display:block;touch-action:none;cursor:crosshair}.drawing-canvas.panning{cursor:grab}.drawing-canvas.panning:active{cursor:grabbing}.peer-cursor{position:absolute;pointer-events:none;display:flex;align-items:center;gap:3px}.peer-cursor small{white-space:nowrap;padding:3px;background:var(--c-surface);border-radius:var(--radius-sm)}.board-history{display:flex;align-items:center;gap:12px;justify-content:space-between;padding:12px 0;border-bottom:1px solid var(--c-border)}.board-history p{font-size:12px;margin:6px 0 0}.material-symbols-outlined{font-size:20px}:global(.board-dialog){max-height:90dvh;overflow:auto;margin-top:5vh}@media(max-width:600px){.board-page{padding:10px;min-height:550px}.board-heading{flex-basis:100%}.board-heading h2{font-size:14px}.board-toolbar{gap:5px}.board-toolbar .el-button{width:28px;height:28px}.board-toolbar :deep(.el-radio-button__inner){padding:5px 7px}.board-toolbar .el-select{width:115px}}
</style>
